        string poison = base + "Poison: you 3 | opponent 0\n";
        string stack = base;
        stack.replace(stack.find("Stack: empty"), 12,
                      "Stack: 1 (top): opponent's Lightning Bolt [instant]");
        string board = base + "Their battlefield: Grizzly Bears (2/2)\n";
